content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body, html, #root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: #0d1117;
  color: #f0f6fc;
}

.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.controls-panel {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10;
  background: rgba(22, 27, 34, 0.75);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(240, 246, 252, 0.1);
  border-radius: 16px;
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: min(90%, 450px);
  max-height: calc(100vh - 48px);
  overflow-y: auto;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.control-group label {
  font-size: 13px;
  font-weight: 500;
  color: #8b949e;
  display: flex;
  justify-content: space-between;
}

.control-group input[type="range"] {
  width: 100%;
  accent-color: #58a6ff;
  cursor: pointer;
}

.control-group input[type="range"]:focus {
  outline: none;
  box-shadow: 0 0 0 2px #58a6ff;
}

.control-group select {
  background: #21262d;
  color: #f0f6fc;
  border: 1px solid #30363d;
  padding: 8px 12px;
  border-radius: 8px;
  font-size: 14px;
  outline: none;
  cursor: pointer;
}

.control-group select:focus {
  border-color: #58a6ff;
  box-shadow: 0 0 0 2px rgba(88, 166, 255, 0.4);
}

.control-group input[type="checkbox"] {
  accent-color: #58a6ff;
  width: 18px;
  height: 18px;
  cursor: pointer;
}

.control-group input[type="checkbox"]:focus {
  outline: none;
  box-shadow: 0 0 0 2px #58a6ff;
}

.checkbox-label {
  display: flex !important;
  flex-direction: row !important;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  color: #f0f6fc !important;
  font-size: 14px !important;
}

.btn {
  background-color: #238636;
  color: #ffffff;
  border: none;
  padding: 10px 16px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:hover {
  background-color: #2ea043;
}

.btn:focus {
  outline: none;
  box-shadow: 0 0 0 2px rgba(46, 160, 67, 0.4);
}

.btn:active {
  transform: scale(0.98);
}

.title {
  font-size: 18px;
  font-weight: 700;
  color: #f0f6fc;
  margin-bottom: 4px;
  letter-spacing: -0.5px;
}

.info-text {
  font-size: 12px;
  color: #8b949e;
  line-height: 1.4;
  text-align: center;
  margin-top: -4px;
}

@media (max-width: 480px) {
  .controls-panel {
    bottom: 16px;
    padding: 16px;
    width: 95%;
    max-height: calc(100vh - 32px);
  }
}

export type ColorTheme = 'neon' | 'fire' | 'ocean' | 'rainbow' | 'monochrome' | 'custom';

export interface ParticleConfig {
  count: number;
  speed: number;
  size: number;
  colorTheme: ColorTheme;
  trail: boolean;
  customColor?: string;
  friction?: number;
}

export interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  color: string;
  alpha: number;
  life: number;
}

import { useEffect, useRef } from 'react';
import { ParticleConfig, Particle } from '../types';

interface ParticleCanvasProps {
  config: ParticleConfig;
}

export default function ParticleCanvas({ config }: ParticleCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const configRef = useRef(config);
  configRef.current = config;

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let width = (canvas.width = window.innerWidth);
    let height = (canvas.height = window.innerHeight);

    const handleResize = () => {
      if (!canvas) return;
      const prevWidth = width;
      const prevHeight = height;
      width = canvas.width = window.innerWidth;
      height = canvas.height = window.innerHeight;

      particles.forEach((p) => {
        p.x = (p.x / prevWidth) * width;
        p.y = (p.y / prevHeight) * height;
      });
    };

    window.addEventListener('resize', handleResize);

    const mouse = {
      x: width / 2,
      y: height / 2,
    };

    const handleMouseMove = (e: MouseEvent) => {
      mouse.x = e.clientX;
      mouse.y = e.clientY;
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches.length > 0) {
        mouse.x = e.touches[0].clientX;
        mouse.y = e.touches[0].clientY;
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('touchmove', handleTouchMove);

    const getColor = (theme: string): string => {
      switch (theme) {
        case 'neon': {
          const neonColors = ['#00ffff', '#ff00ff', '#00ff66', '#ffff00'];
          return neonColors[Math.floor(Math.random() * neonColors.length)];
        }
        case 'fire': {
          const fireColors = ['#ff3300', '#ff9900', '#ffcc00', '#ff3366'];
          return fireColors[Math.floor(Math.random() * fireColors.length)];
        }
        case 'ocean': {
          const oceanColors = ['#0066ff', '#00ccff', '#00ffff', '#3333ff'];
          return oceanColors[Math.floor(Math.random() * oceanColors.length)];
        }
        case 'rainbow':
          return `hsl(${Math.random() * 360}, 100%, 70%)`;
        case 'monochrome':
        default:
          return '#ffffff';
      }
    };

    let particles: Particle[] = [];

    const initParticles = () => {
      particles = [];
      for (let i = 0; i < configRef.current.count; i++) {
        particles.push({
          x: Math.random() * width,
          y: Math.random() * height,
          vx: (Math.random() - 0.5) * 2,
          vy: (Math.random() - 0.5) * 2,
          size: Math.random() * configRef.current.size + 1,
          color: getColor(configRef.current.colorTheme),
          alpha: Math.random() * 0.8 + 0.2,
          life: Math.random() * 100 + 50,
        });
      }
    };

    initParticles();

    let lastColorTheme = configRef.current.colorTheme;

    const render = () => {
      const currentConfig = configRef.current;

      if (currentConfig.colorTheme !== lastColorTheme) {
        lastColorTheme = currentConfig.colorTheme;
        particles.forEach((p) => {
          p.color = getColor(currentConfig.colorTheme);
        });
      }

      if (currentConfig.trail) {
        ctx.fillStyle = 'rgba(13, 17, 23, 0.2)';
        ctx.fillRect(0, 0, width, height);
      } else {
        ctx.clearRect(0, 0, width, height);
      }

      if (particles.length < currentConfig.count) {
        while (particles.length < currentConfig.count) {
          particles.push({
            x: Math.random() * width,
            y: Math.random() * height,
            vx: (Math.random() - 0.5) * 2,
            vy: (Math.random() - 0.5) * 2,
            size: Math.random() * currentConfig.size + 1,
            color: getColor(currentConfig.colorTheme),
            alpha: Math.random() * 0.8 + 0.2,
            life: Math.random() * 100 + 50,
          });
        }
      } else if (particles.length > currentConfig.count) {
        particles = particles.slice(0, currentConfig.count);
      }

      particles.forEach((p) => {
        // 自律的なランダムウォークの揺らぎを追加
        p.vx += (Math.random() - 0.5) * 0.5;
        p.vy += (Math.random() - 0.5) * 0.5;

        // Move towards mouse
        const dx = mouse.x - p.x;
        const dy = mouse.y - p.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist > 1) {
          p.vx += (dx / dist) * (0.1 * currentConfig.speed);
          p.vy += (dy / dist) * (0.1 * currentConfig.speed);
        }

        // Apply friction
        p.vx *= 0.95;
        p.vy *= 0.95;

        p.x += p.vx;
        p.y += p.vy;

        // Screen boundary wrapping
        if (p.x < 0) p.x = width;
        if (p.x > width) p.x = 0;
        if (p.y < 0) p.y = height;
        if (p.y > height) p.y = 0;

        // Draw particle
        ctx.save();
        ctx.globalAlpha = p.alpha;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * (currentConfig.size / 3), 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('touchmove', handleTouchMove);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="canvas-container">
      <canvas ref={canvasRef} />
    </div>
  );
}

import { useState, useEffect } from 'react';
import ParticleCanvas from './components/ParticleCanvas';
import Controls from './components/Controls';
import { ParticleConfig } from './types';

const STORAGE_KEY = 'particle_animation_config_v1';

const defaultConfig: ParticleConfig = {
  count: 300,
  speed: 2.0,
  size: 3.0,
  colorTheme: 'neon',
  trail: true,
};

export default function App() {
  const [config, setConfig] = useState<ParticleConfig>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        return JSON.parse(saved);
      }
    } catch (e) {
      console.error('Failed to load config from localStorage', e);
    }
    return defaultConfig;
  });

  const [showConfirm, setShowConfirm] = useState(false);
  const [isResetting, setIsResetting] = useState(false);

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
    } catch (e) {
      console.error('Failed to save config to localStorage', e);
    }
  }, [config]);

  const handleResetClick = () => {
    setShowConfirm(true);
  };

  const handleConfirmReset = () => {
    setIsResetting(true);
    setTimeout(() => {
      setConfig(defaultConfig);
      try {
        localStorage.removeItem(STORAGE_KEY);
      } catch (e) {
        console.error('Failed to remove config from localStorage', e);
      }
      setIsResetting(false);
      setShowConfirm(false);
    }, 300);
  };

  const handleCancelReset = () => {
    setShowConfirm(false);
  };

  return (
    <div className="app-container" style={{ opacity: isResetting ? 0.4 : 1, transition: 'opacity 0.3s ease' }}>
      <ParticleCanvas config={config} />
      <Controls config={config} onChange={setConfig} onReset={handleResetClick} />

      {showConfirm && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100vw',
          height: '100vh',
          background: 'rgba(0, 0, 0, 0.65)',
          backdropFilter: 'blur(6px)',
          WebkitBackdropFilter: 'blur(6px)',
          zIndex: 100,
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          animation: 'fadeIn 0.2s ease'
        }}>
          <div style={{
            background: '#161b22',
            border: '1px solid rgba(240, 246, 252, 0.1)',
            borderRadius: '16px',
            padding: '24px',
            width: 'min(90%, 380px)',
            boxShadow: '0 16px 48px rgba(0, 0, 0, 0.6)',
            display: 'flex',
            flexDirection: 'column',
            gap: '16px',
            color: '#f0f6fc'
          }}>
            <h2 className="title" style={{ fontSize: '16px' }}>設定のリセット</h2>
            <p className="info-text" style={{ textAlign: 'left', marginTop: 0 }}>
              すべての設定をデフォルト値に戻しますか？この操作を行うと現在のカスタマイズは失われます。
            </p>
            <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end', marginTop: '8px' }}>
              <button 
                onClick={handleCancelReset}
                style={{
                  background: '#21262d',
                  color: '#f0f6fc',
                  border: '1px solid #30363d',
                  padding: '8px 16px',
                  borderRadius: '8px',
                  fontSize: '14px',
                  cursor: 'pointer',
                  fontWeight: 500
                }}
              >
                キャンセル
              </button>
              <button 
                onClick={handleConfirmReset}
                style={{
                  background: '#da3633',
                  color: '#ffffff',
                  border: 'none',
                  padding: '8px 16px',
                  borderRadius: '8px',
                  fontSize: '14px',
                  cursor: 'pointer',
                  fontWeight: 600
                }}
              >
                リセットする
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
